def correct_bracketing(brackets: str):
    opening_brackets = "<"
    closing_brackets = ">"

    if any(char not in opening_brackets + closing_brackets for char in brackets):
        return False

    if brackets.count(opening_brackets) != brackets.count(closing_brackets):
        return False

    stack = []
    for bracket in brackets:
        if bracket == opening_brackets:
            stack.append(bracket)
        elif bracket == closing_brackets:
            if not stack:
                return False
            stack.pop()

    return len(stack) == 0

